import { config } from "@/lib/config";
import { publishedLocales } from "@/i18n/locales";

export const revalidate = 3600;

/** Sitemap index pointing at the per-locale sitemaps generated by app/sitemap.ts. */
export function GET() {
  const lastmod = new Date().toISOString();
  const body = `<?xml version="1.0" encoding="UTF-8"?>
<sitemapindex xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">
${publishedLocales
  .map((l) => `  <sitemap><loc>${config.siteUrl}/sitemap/${l}.xml</loc><lastmod>${lastmod}</lastmod></sitemap>`)
  .join("\n")}
</sitemapindex>
`;
  return new Response(body, { headers: { "Content-Type": "application/xml; charset=utf-8" } });
}
